) values
  ('front_squat', 'Sentadilla frontal', array['front squat', 'sentadilla delantera', 'sentadilla con barra delante']::text[], 'strength', 'weight_reps', array['barbell', 'rack']::text[], false, true, 180, 'Barra sobre los hombros delanteros, codos altos y torso muy erguido.'),
