  ('nordic_curl', 'Curl nórdico', array['nordic curl', 'nordic hamstring curl', 'nórdicos', 'curl nordico', 'glute ham raise']::text[], 'strength', 'reps', array['bodyweight', 'mat']::text[], false, false, 90, 'De rodillas con los tobillos sujetos, deja caer el cuerpo recto lo más lento posible.'),
  ('db_bench_press', 'Press banca con mancuernas', array['dumbbell bench press', 'press con mancuernas', 'press plano con mancuernas', 'db bench']::text[], 'strength', 'weight_reps', array['dumbbell', 'bench']::text[], false, true, 120, 'Omóplatos juntos, bajar las mancuernas a los lados del pecho y subir juntándolas.'),
  ('incline_bench_press', 'Press inclinado con barra', array['incline bench press', 'press inclinado', 'incline barbell press', 'banca inclinada']::text[], 'strength', 'weight_reps', array['barbell', 'bench', 'rack']::text[], false, true, 150, 'Banco a 30–45°, barra a la parte alta del pecho y omóplatos juntos.'),
  ('db_fly', 'Aperturas con mancuernas', array['dumbbell fly', 'dumbbell flyes', 'aperturas', 'flyes', 'aperturas en banco plano']::text[], 'strength', 'weight_reps', array['dumbbell', 'bench']::text[], false, false, 75, 'Codos ligeramente doblados y fijos; abre en arco hasta notar el pecho.'),
