  ('rear_delt_fly', 'Pájaros con mancuernas', array['rear delt fly', 'bent over reverse fly', 'pájaros', 'aperturas invertidas', 'reverse fly']::text[], 'strength', 'weight_reps', array['dumbbell']::text[], false, false, 60, 'Torso inclinado, abre los brazos casi rectos hacia los lados con peso ligero.'),
  ('front_raise', 'Elevaciones frontales', array['front raise', 'front raises', 'elevación frontal', 'elevaciones al frente']::text[], 'strength', 'weight_reps', array['dumbbell', 'plate', 'cable']::text[], false, false, 60, 'Sube los brazos al frente hasta la altura de los hombros sin balancearte.'),
  ('upright_row', 'Remo al mentón', array['upright row', 'remo vertical', 'remo al cuello', 'jalón al mentón']::text[], 'strength', 'weight_reps', array['barbell', 'dumbbell', 'cable', 'ez_bar']::text[], false, true, 75, 'Agarre a la anchura de los hombros y subir los codos solo hasta la altura de los hombros.'),
  ('chin_up', 'Dominadas supinas (chin-up)', array['chin up', 'chin-ups', 'dominadas supinas', 'dominadas con palmas hacia ti', 'chinups']::text[], 'strength', 'reps', array['pullup_bar', 'bodyweight']::text[], false, true, 150, 'Palmas hacia ti y agarre a la anchura de los hombros: más bíceps que la prona.'),
  ('inverted_row', 'Remo invertido', array['inverted row', 'australian pull-up', 'remo australiano', 'dominada australiana', 'body row']::text[], 'strength', 'reps', array['barbell', 'rack', 'rings', 'bodyweight']::text[], false, true, 90, 'Bajo una barra baja, cuerpo recto, tira del pecho hacia la barra.'),
