  ('ez_bar_curl', 'Curl con barra Z', array['ez bar curl', 'curl barra z', 'ez curl', 'curl con barra ez']::text[], 'strength', 'weight_reps', array['ez_bar']::text[], false, false, 75, 'Agarre en las curvas de la barra: menos tensión en las muñecas.'),
  ('concentration_curl', 'Curl concentrado', array['concentration curl', 'curl concentración', 'curl sentado a una mano']::text[], 'strength', 'weight_reps', array['dumbbell', 'bench']::text[], true, false, 60, 'Sentado, codo apoyado en la cara interna del muslo; solo se mueve el antebrazo.'),
