  ('overhead_triceps_extension', 'Extensión de tríceps sobre la cabeza', array['overhead triceps extension', 'extensión tras nuca', 'copa', 'tríceps tras nuca', 'extensión de tríceps con mancuerna']::text[], 'strength', 'weight_reps', array['dumbbell', 'kettlebell', 'ez_bar']::text[], false, false, 60, 'Mancuerna tras la cabeza con los codos apuntando al techo; estira los codos.'),
  ('triceps_kickback', 'Patada de tríceps', array['triceps kickback', 'kickback de tríceps', 'patada trasera de tríceps']::text[], 'strength', 'weight_reps', array['dumbbell', 'cable']::text[], true, false, 60, 'Torso inclinado y brazo pegado al cuerpo; estira el codo hacia atrás.'),
  ('close_grip_bench', 'Press banca agarre estrecho', array['close grip bench press', 'close-grip bench', 'press cerrado', 'banca agarre cerrado']::text[], 'strength', 'weight_reps', array['barbell', 'bench', 'rack']::text[], false, true, 150, 'Agarre a la anchura de los hombros y codos pegados: más tríceps.'),
  ('landmine_press', 'Press landmine', array['landmine press', 'press en mina', 'press a una mano con barra en punta']::text[], 'strength', 'weight_reps', array['landmine', 'barbell']::text[], true, true, 90, 'Barra anclada en el suelo; empuja el extremo hacia delante y arriba.'),
  ('db_pullover', 'Pullover con mancuerna', array['dumbbell pullover', 'pullover', 'pull over']::text[], 'strength', 'weight_reps', array['dumbbell', 'bench']::text[], false, false, 75, 'Tumbado, baja la mancuerna detrás de la cabeza con los codos algo doblados.')
on conflict (id) do update set
  name = excluded.name,
  aliases = excluded.aliases,
  category = excluded.category,
  tracking_type = excluded.tracking_type,
  equipment = excluded.equipment,
  is_unilateral = excluded.is_unilateral,
  is_compound = excluded.is_compound,
  default_rest_s = excluded.default_rest_s,
  technique_notes = excluded.technique_notes
where public.exercises.owner_id is null;

-- Músculos: se reescriben para que la semilla sea la fuente de verdad.
delete from public.exercise_muscles where exercise_id in ('front_squat', 'sumo_deadlift', 'trap_bar_deadlift', 'good_morning', 'step_up', 'reverse_lunge', 'walking_lunge', 'glute_bridge', 'single_leg_rdl', 'nordic_curl', 'db_bench_press', 'incline_bench_press', 'db_fly', 'arnold_press', 'db_shoulder_press', 'shrug', 'rear_delt_fly', 'front_raise', 'upright_row', 'chin_up', 'inverted_row', 'hammer_curl', 'ez_bar_curl', 'concentration_curl', 'skull_crusher', 'overhead_triceps_extension', 'triceps_kickback', 'close_grip_bench', 'landmine_press', 'db_pullover');

on conflict (exercise_id, muscle_id) do update set role = excluded.role;

-- Técnica (pasos clave y errores típicos).
update public.exercises e set
  technique_steps = v.steps,
  technique_mistakes = v.mistakes
from (values
  ('front_squat', array['Apoya la barra sobre los deltoides delanteros, cerca del cuello, con los dedos bajo la barra.', 'Sube los codos hasta que los brazos queden casi paralelos al suelo.', 'Baja con el torso erguido y las rodillas hacia delante, al menos hasta paralelo.', 'Sube empujando con todo el pie y manteniendo los codos altos.']::text[], array['Dejar caer los codos: la barra rueda hacia delante.', 'Inclinar el torso como en la sentadilla trasera.', 'Agarrar la barra con toda la mano si falta movilidad de muñeca (mejor cruzar brazos o correas).']::text[]),
  ('sumo_deadlift', array['Abre los pies bastante más que los hombros, con las puntas hacia fuera y la barra sobre la mitad del pie.', 'Coge la barra con los brazos estirados por dentro de las rodillas.', 'Empuja las rodillas hacia fuera, saca pecho y tensa la espalda.', 'Empuja el suelo con las piernas hasta quedar erguido con la cadera extendida.']::text[], array['Rodillas que se van hacia dentro al subir.', 'Subir la cadera antes que la barra.', 'Redondear la espalda al arrancar.']::text[]),
  ('trap_bar_deadlift', array['Colócate en el centro de la barra con los pies a la anchura de la cadera.', 'Baja la cadera y coge los agarres con la espalda neutra y el pecho alto.', 'Empuja el suelo y sube hasta estar erguido, con los hombros atrás.', 'Baja controlando por el mismo camino.']::text[], array['Ponerse descentrado dentro de la barra.', 'Redondear la espalda abajo.', 'Echar los hombros atrás de más arriba.']::text[]),
  ('good_morning', array['Coloca una barra ligera en la espalda alta, como en la sentadilla.', 'Con las rodillas algo flexionadas, lleva la cadera atrás e inclina el torso.', 'Baja hasta notar los isquios (torso casi paralelo o antes) con la espalda neutra.', 'Sube empujando la cadera hacia delante.']::text[], array['Redondear la espalda.', 'Doblar mucho las rodillas y convertirlo en sentadilla.', 'Usar mucho peso: es un ejercicio de control.']::text[]),
  ('step_up', array['Ponte frente a un cajón a la altura de la rodilla, con mancuernas si quieres.', 'Apoya un pie entero en el cajón.', 'Sube empujando con esa pierna hasta quedar de pie sobre el cajón.', 'Baja despacio con la misma pierna y repite antes de cambiar.']::text[], array['Impulsarse con la pierna de abajo.', 'Rodilla de la pierna de arriba hacia dentro.', 'Cajón demasiado alto para tu movilidad.']::text[]),
  ('reverse_lunge', array['De pie con los pies a la anchura de la cadera, con mancuernas o sin peso.', 'Da un paso largo hacia atrás y baja la rodilla trasera cerca del suelo.', 'La rodilla delantera queda sobre el pie y el torso erguido.', 'Vuelve empujando con el talón delantero.']::text[], array['Paso demasiado corto: la rodilla delantera se adelanta mucho.', 'Inclinar el torso hacia delante.', 'Golpear la rodilla contra el suelo.']::text[]),
  ('walking_lunge', array['Da un paso largo adelante y baja hasta que la rodilla trasera casi toque el suelo.', 'Empuja con la pierna delantera y trae la trasera directamente a la siguiente zancada.', 'Mantén el torso erguido y el ritmo constante.']::text[], array['Pasos cortos con la rodilla muy por delante del pie.', 'Perder el equilibrio por poner los pies en línea (déjalos a la anchura de la cadera).', 'Inclinarse hacia delante.']::text[]),
  ('glute_bridge', array['Túmbate boca arriba con las rodillas dobladas y los pies cerca de los glúteos.', 'Empuja con los talones y sube la cadera apretando los glúteos.', 'Arriba, rodillas, cadera y hombros quedan en línea; aguanta un segundo.', 'Baja despacio sin apoyar del todo.']::text[], array['Arquear la lumbar arriba en vez de apretar glúteos.', 'Pies demasiado lejos: trabajan más los isquios.', 'Rodillas que se abren o se cierran.']::text[]),
  ('single_leg_rdl', array['Ponte sobre una pierna con la rodilla algo flexionada y el peso en la mano contraria.', 'Inclina el torso llevando la otra pierna atrás, en línea con la espalda.', 'Baja hasta notar el isquio con la cadera nivelada.', 'Sube apretando el glúteo de la pierna de apoyo.']::text[], array['Abrir la cadera hacia el lado de la pierna que sube.', 'Redondear la espalda para llegar más abajo.', 'Bloquear la rodilla de apoyo.']::text[]),
  ('nordic_curl', array['Arrodíllate sobre una esterilla con los tobillos sujetos (compañero, banco o barra).', 'Con el cuerpo recto de rodillas a cabeza, déjate caer hacia delante muy despacio.', 'Frena con los isquios todo lo que puedas y amortigua con las manos.', 'Vuelve empujándote con las manos y repite.']::text[], array['Doblar la cadera para que sea más fácil.', 'Caer de golpe sin frenar.', 'Hacer muchas series el primer día: da muchas agujetas.']::text[]),
  ('db_bench_press', array['Siéntate con las mancuernas en los muslos y túmbate llevándolas al pecho.', 'Junta los omóplatos y apoya bien los pies.', 'Baja las mancuernas a los lados del pecho con los codos a unos 45° del cuerpo.', 'Empuja hacia arriba hasta casi juntarlas sobre el pecho.']::text[], array['Codos abiertos a 90°: carga el hombro.', 'Soltar las mancuernas de golpe al acabar (bájalas a los muslos).', 'Recorrido corto.']::text[]),
  ('incline_bench_press', array['Ajusta el banco a 30–45° y túmbate con los ojos bajo la barra.', 'Coge la barra algo más ancha que los hombros y junta los omóplatos.', 'Baja la barra a la parte alta del pecho controlando.', 'Empuja hacia arriba y algo atrás hasta estirar los brazos.']::text[], array['Banco demasiado inclinado: se convierte en press de hombro.', 'Rebotar la barra en el pecho.', 'Levantar los glúteos del banco.']::text[]),
  ('db_fly', array['Túmbate con las mancuernas sobre el pecho y las palmas enfrentadas.', 'Dobla un poco los codos y mantén ese ángulo todo el ejercicio.', 'Abre los brazos en arco hasta que las manos queden a la altura del pecho.', 'Cierra el arco apretando el pecho hasta juntar las mancuernas.']::text[], array['Estirar del todo los codos: carga la articulación.', 'Bajar demasiado por detrás de la línea de los hombros.', 'Usar tanto peso que se convierte en un press.']::text[]),
  ('arnold_press', array['Siéntate con la espalda apoyada y las mancuernas delante de la cara, palmas hacia ti.', 'Empuja hacia arriba girando las palmas hacia delante a la vez.', 'Arriba, brazos casi estirados; baja deshaciendo el giro.']::text[], array['Arquear la lumbar al empujar.', 'Girar de golpe al final en vez de durante el recorrido.', 'Chocar las mancuernas arriba.']::text[]),
  ('db_shoulder_press', array['Siéntate en un banco a 80–90° con las mancuernas a la altura de los hombros.', 'Codos algo por delante del cuerpo y palmas hacia delante.', 'Empuja hacia arriba hasta casi estirar los brazos.', 'Baja controlando hasta la altura de las orejas.']::text[], array['Despegar la espalda y arquear la lumbar.', 'Bajar poco.', 'Codos muy hacia atrás.']::text[]),
  ('shrug', array['De pie con el peso en las manos y los brazos estirados.', 'Sube los hombros hacia las orejas en línea recta.', 'Aguanta un segundo arriba y baja despacio.']::text[], array['Girar los hombros en círculos.', 'Doblar los codos para ayudarse.', 'Adelantar la cabeza.']::text[]),
  ('rear_delt_fly', array['Inclina el torso casi paralelo al suelo con la espalda recta y las rodillas algo flexionadas.', 'Deja colgar las mancuernas bajo el pecho con los codos ligeramente doblados.', 'Abre los brazos hacia los lados hasta la altura de los hombros.', 'Baja despacio.']::text[], array['Levantar el torso para subir el peso.', 'Encoger los hombros.', 'Juntar los omóplatos en exceso: trabaja más el trapecio.']::text[]),
  ('front_raise', array['De pie con las mancuernas delante de los muslos.', 'Sube los brazos casi estirados al frente hasta la altura de los hombros.', 'Baja despacio sin dejarlos caer.']::text[], array['Balancear el cuerpo para subir.', 'Subir por encima de la cabeza.', 'Encoger los hombros.']::text[]),
  ('upright_row', array['De pie, coge la barra con un agarre a la anchura de los hombros.', 'Sube la barra pegada al cuerpo llevando los codos hacia arriba y fuera.', 'Para cuando los codos lleguen a la altura de los hombros y baja despacio.']::text[], array['Agarre muy estrecho y subir hasta la barbilla: molesta al hombro.', 'Dar tirones con la espalda.', 'Muñecas por encima de los codos.']::text[]),
  ('chin_up', array['Cuélgate con las palmas hacia ti, a la anchura de los hombros.', 'Activa los hombros llevándolos abajo antes de tirar.', 'Sube hasta que la barbilla pase la barra, con los codos hacia las costillas.', 'Baja despacio hasta estirar los brazos.']::text[], array['Balanceo o patadas para subir.', 'No estirar los brazos abajo.', 'Adelantar la barbilla sin subir el cuerpo.']::text[]),
  ('inverted_row', array['Coloca una barra a la altura de la cintura y cuélgate debajo con los brazos estirados.', 'Pon el cuerpo recto de talones a cabeza, con glúteos y abdomen apretados.', 'Tira llevando el pecho a la barra y juntando los omóplatos.', 'Baja despacio. Más fácil con las rodillas dobladas; más difícil con los pies elevados.']::text[], array['Dejar caer la cadera.', 'Llevar la barbilla a la barra en vez del pecho.', 'Recorrido corto.']::text[]),
  ('hammer_curl', array['De pie con las mancuernas a los lados y las palmas mirando al cuerpo.', 'Sube flexionando los codos sin girar las muñecas.', 'Baja despacio hasta estirar los brazos.']::text[], array['Mover los codos hacia delante.', 'Balancear el cuerpo.', 'Bajar sin control.']::text[]),
  ('ez_bar_curl', array['De pie, coge la barra Z por las curvas con las palmas hacia arriba.', 'Codos pegados al cuerpo y hombros quietos.', 'Sube la barra flexionando los codos y baja despacio.']::text[], array['Echar el cuerpo atrás para subir.', 'Separar los codos del cuerpo.', 'Medio recorrido.']::text[]),
  ('concentration_curl', array['Siéntate con las piernas abiertas y apoya el codo en la cara interna del muslo.', 'Sube la mancuerna hacia el hombro girando un poco la palma hacia ti.', 'Baja despacio hasta estirar el brazo.']::text[], array['Mover el hombro o el tronco.', 'Despegar el codo del muslo.', 'Ir deprisa.']::text[]),
  ('skull_crusher', array['Túmbate en el banco con la barra sobre el pecho y los brazos estirados.', 'Inclina un poco los brazos hacia la cabeza.', 'Baja la barra hacia la frente doblando solo los codos.', 'Estira los codos para volver arriba.']::text[], array['Abrir los codos hacia fuera.', 'Mover los hombros y convertirlo en un pullover.', 'Bajar sin control hacia la cara.']::text[]),
  ('overhead_triceps_extension', array['Sentado o de pie, sujeta una mancuerna con las dos manos por encima de la cabeza.', 'Baja la mancuerna detrás de la cabeza doblando los codos, que apuntan arriba.', 'Estira los codos para subir sin moverlos de sitio.']::text[], array['Abrir los codos.', 'Arquear la lumbar.', 'Recorrido corto.']::text[]),
  ('triceps_kickback', array['Apoya una mano y una rodilla en el banco con la espalda recta.', 'Sube el codo del otro brazo hasta la altura del torso.', 'Estira el codo llevando la mancuerna hacia atrás y vuelve despacio.']::text[], array['Dejar caer el codo durante el ejercicio.', 'Balancear la mancuerna.', 'Demasiado peso.']::text[]),
  ('close_grip_bench', array['Túmbate como en el press banca y coge la barra a la anchura de los hombros.', 'Junta los omóplatos y apoya bien los pies.', 'Baja la barra a la parte baja del pecho con los codos pegados al cuerpo.', 'Empuja hasta estirar los brazos.']::text[], array['Agarre tan estrecho que molesta a las muñecas.', 'Abrir los codos.', 'Rebotar en el pecho.']::text[]),
  ('landmine_press', array['Ancla un extremo de la barra en un rincón o en un soporte landmine.', 'Sujeta el otro extremo a la altura del hombro, de pie o de rodillas.', 'Empuja la barra hacia delante y arriba hasta estirar el brazo.', 'Baja controlando hasta el hombro.']::text[], array['Arquear la lumbar al empujar.', 'Girar el tronco para ayudarse.', 'Dejar caer la barra al bajar.']::text[]),
  ('db_pullover', array['Túmbate en el banco y sujeta una mancuerna con las dos manos sobre el pecho.', 'Con los codos ligeramente doblados, bájala en arco detrás de la cabeza.', 'Baja hasta notar el estiramiento sin arquear la lumbar.', 'Vuelve en arco hasta encima del pecho.']::text[], array['Doblar y estirar los codos (se convierte en un tríceps).', 'Arquear la espalda para bajar más.', 'Demasiado peso.']::text[])
) as v (id, steps, mistakes)
where e.id = v.id and e.owner_id is null;
